+      box-shadow: 0 24px 80px -40px var(--color-shadow);
+    }
+
+    h1 {
+      margin: 0 0 12px;
+      font-size: 1.9rem;
+      line-height: 1.15;
+    }
+
+    .intro {
+      margin: 0 0 28px;
+      color: var(--color-muted-text);
+      line-height: 1.5;
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 18px;
+      border: 1px solid var(--color-border);
+      border-radius: 16px;
+      background: #0f172a;
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: start;
+      gap: 12px;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin: 0.15rem 0 0;
+      accent-color: var(--color-accent);
+      flex: none;
+    }
+
+    label {
+      font-size: 1rem;
+      line-height: 1.5;
+      cursor: pointer;
+    }
+
+    .required-indicator {
+      color: var(--color-danger);
+      font-weight: 700;
+    }
+
+    .helper-text,
+    .error-text,
+    .status-message {
+      margin: 0;
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      color: var(--color-muted-text);
+    }
+
+    .error-text {
+      color: var(--color-danger);
+    }
+
+    .status-message {
+      min-height: 1.5em;
+      color: var(--color-success);
+    }
+
+    button {
+      border: 1px solid #6366f1;
+      border-radius: 999px;
+      padding: 0.95rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: var(--color-text);
+      background: linear-gradient(180deg, #818cf8, #6366f1);
+      cursor: pointer;
+    }
+
+    input:focus-visible,
+    button:focus-visible {
+      outline: 3px solid var(--color-focus);
+      outline-offset: 3px;
+    }
+
+    input[aria-invalid="true"] {
+      outline: 2px solid var(--color-danger);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 480px) {
+      body {
+        padding: 16px;
+      }
+
+      .card {
+        padding: 24px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .skip-link,
+      .card,
+      .form-field,
+      button {
+        border-color: ButtonText;
+      }
+
+      .skip-link,
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+      }
+
+      .card,
+      .form-field {
+        background: Canvas;
+        color: CanvasText;
+      }
+
+      .required-indicator,
+      .error-text,
+      .status-message {
+        color: CanvasText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content" tabindex="-1">
+    <section class="card" aria-labelledby="form-title">
+      <h1 id="form-title">Confirm your consent</h1>
+      <p class="intro">Please confirm that you agree to the terms of use before submitting this form.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="terms-consent"
+              name="terms-consent"
+              type="checkbox"
+              required
+              aria-describedby="terms-help terms-error"
+            >
+            <label for="terms-consent">I agree to the terms of use <span class="required-indicator" aria-hidden="true">*</span></label>
+          </div>
+          <p id="terms-help" class="helper-text">Required to continue.</p>
+          <p id="terms-error" class="error-text" hidden></p>
+        </div>
+
+        <button type="submit">Submit</button>
+        <p id="form-status" class="status-message" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms-consent');
+    const errorText = document.getElementById('terms-error');
+    const statusMessage = document.getElementById('form-status');
+
+    function showError(message) {
+      errorText.textContent = `Error: ${message}`;
+      errorText.hidden = false;
+      checkbox.setAttribute('aria-invalid', 'true');
+      statusMessage.textContent = '';
+    }
+
+    function clearError() {
+      errorText.hidden = true;
+      errorText.textContent = '';
+      checkbox.removeAttribute('aria-invalid');
+    }
+
+    checkbox.addEventListener('change', () => {
+      if (checkbox.checked) {
+        clearError();
+      }
+    });
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      if (!checkbox.checked) {
+        showError('You must agree to the terms of use before continuing.');
+        checkbox.focus();
+        return;
+      }
+
+      clearError();
+      statusMessage.textContent = 'Consent captured. Form submitted successfully.';
+    });
+  </script>
+</body>
+</html>
*** End Patch
